import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"When something fails","description":"","frontmatter":{},"headers":[],"relativePath":"failures.md","filePath":"failures.md"}'),i={name:"failures.md"};function s(n,e,r,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="when-something-fails" tabindex="-1">When something fails <a class="header-anchor" href="#when-something-fails" aria-label="Permalink to &quot;When something fails&quot;">​</a></h1><p>If a step of an install, uninstall, upgrade or account change fails, ripeat prints the plain error as before, and when it recognises the failure it adds a likely cause and something to try:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Installing git failed: exit status 100</span></span>\n<span class="line"><span>Why it probably failed: The package manager does not know this package name here.</span></span>\n<span class="line"><span>  What to try: Refresh its package list (for example `sudo apt-get update`), then check the name with `ripeat find &lt;tool&gt;`.</span></span>\n<span class="line"><span>Rolling back this run...</span></span></code></pre></div><p>It is a fixed list of rules, not AI: the same failure always gets the same words, and a failure no rule recognises is simply left as the plain error. ripeat never makes up a cause. The error itself and the exit code are unchanged, so scripts that read them keep working.</p><h2 id="how-it-decides" tabindex="-1">How it decides <a class="header-anchor" href="#how-it-decides" aria-label="Permalink to &quot;How it decides&quot;">​</a></h2><p>When a command fails, ripeat keeps the last few kilobytes of what it printed (it still shows all of it as it happens). The rules look for known phrases in that text and in the error. Up to three explanations are shown, most specific first; extra ones start with &quot;It may also be&quot;.</p><h2 id="what-it-recognises" tabindex="-1">What it recognises <a class="header-anchor" href="#what-it-recognises" aria-label="Permalink to &quot;What it recognises&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cause shown</th><th>Typical signs</th></tr></thead><tbody><tr><td>The administrator policy forbids it</td><td><code>blocked by the administrator policy</code> (<a href="./admin-policy">Administrator policy</a>)</td></tr><tr><td><code>sudo</code> wanted a password and had no terminal</td><td><code>a password is required</code>, <code>no tty present</code></td></tr><tr><td>Homebrew refuses to run as root</td><td><code>Don&#39;t run this as root</code></td></tr><tr><td>Administrator rights are missing (not shown when ripeat is already root or administrator)</td><td><code>permission denied</code>, <code>access is denied</code>, <code>operation not permitted</code></td></tr><tr><td>The package manager does not know the name</td><td><code>Unable to locate package</code>, <code>No match for argument</code>, <code>target not found</code>, <code>No package found</code>, <code>No available formula or cask</code></td></tr><tr><td>Another package manager is running</td><td><code>Could not get lock</code>, <code>unable to lock database</code>, <code>database is locked</code></td></tr><tr><td>GitHub is limiting requests</td><td><code>rate limit</code> (set <code>GITHUB_TOKEN</code>)</td></tr><tr><td>The download&#39;s SHA-256 is wrong (nothing was installed)</td><td><code>checksum mismatch</code>, <code>changed since ripeat.lock</code></td></tr><tr><td>The machine does not trust the server&#39;s certificate</td><td><code>x509:</code>, <code>certificate verify failed</code>, <code>unable to get local issuer certificate</code></td></tr><tr><td>The server could not be reached</td><td><code>Could not resolve host</code>, <code>connection timed out</code>, <code>i/o timeout</code>, <code>dial tcp</code></td></tr><tr><td>The disk is full</td><td><code>No space left on device</code></td></tr><tr><td>A company or system policy blocks it</td><td><code>blocked by group policy</code>, <code>AppLocker</code>, <code>SmartScreen</code></td></tr><tr><td>macOS Gatekeeper blocked an unsigned program</td><td><code>cannot be opened because the developer cannot be verified</code></td></tr><tr><td>Dependencies cannot be satisfied</td><td><code>unmet dependencies</code>, <code>held broken packages</code>, <code>conflicts with</code></td></tr><tr><td>A program the step needs is missing</td><td><code>command not found</code>, <code>: not found</code>, <code>is not recognized as an internal or external command</code></td></tr><tr><td>The file is no longer where the recipe says</td><td><code>404 Not Found</code> (not shown when the package manager simply did not know the name)</td></tr></tbody></table><p>The advice differs by system where it matters: on Windows it says to open a terminal as Administrator, and elsewhere to run <code>sudo -v</code> first. Both mention <code>--scope user</code> for tools that need no admin rights (<a href="./privileges">Admin rights</a>).</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Only failures during a run are explained. Mistakes found before anything runs (a bad recipe, a blocked plan, an unknown tool) already stop with a specific message, and <code>ripeat validate</code> finds file mistakes earlier.</li><li>It matches English phrases. A tool printing in another language may go unrecognised, and then the failure is left as the plain error.</li><li>The cause is the likeliest one, not proof. The tool&#39;s own output, shown above it, is the evidence.</li><li>A failed rollback step is listed as before; it does not get an explanation.</li></ul>',11)])])}const u=t(i,[["render",s]]);export{m as __pageData,u as default};
